<?php require_once __DIR__."/../config/app.php";require_role("Admin LP2M");$id=(int)($_GET["id"]??0);$roles=$pdo->query("SELECT * FROM roles ORDER BY id")->fetchAll();$d=["name"=>"","email"=>"","role_id"=>"","is_active"=>1];if($id){$st=$pdo->prepare("SELECT * FROM users WHERE id=?");$st->execute([$id]);$d=$st->fetch();if(!$d)exit("Data tidak ditemukan.");}if($_SERVER["REQUEST_METHOD"]==="POST"){require_post_csrf();$d["name"]=post_string("name");$d["email"]=post_string("email");$d["role_id"]=post_string("role_id");$d["is_active"]=isset($_POST["is_active"])?1:0;$pass=(string)($_POST["password"]??"");try{if($id){if($pass!==""){$pdo->prepare("UPDATE users SET name=?,email=?,role_id=?,password=?,is_active=? WHERE id=?")->execute([$d["name"],$d["email"],$d["role_id"],password_hash($pass,PASSWORD_DEFAULT),$d["is_active"],$id]);}else{$pdo->prepare("UPDATE users SET name=?,email=?,role_id=?,is_active=? WHERE id=?")->execute([$d["name"],$d["email"],$d["role_id"],$d["is_active"],$id]);}flash("success","Pengguna diperbarui.");}else{if($pass==="")throw new RuntimeException("Password wajib diisi.");$pdo->prepare("INSERT INTO users(name,email,role_id,password,is_active) VALUES(?,?,?,?,?)")->execute([$d["name"],$d["email"],$d["role_id"],password_hash($pass,PASSWORD_DEFAULT),$d["is_active"]]);flash("success","Pengguna ditambahkan.");}redirect("index.php");}catch(Throwable $e){$err="Data tidak valid atau email sudah digunakan.";}}$pageTitle=$id?"Edit Pengguna":"Tambah Pengguna";require __DIR__."/../partials/header.php";?><h3 class="fw-bold"><?=$id?"Edit":"Tambah"?> Pengguna</h3><?php if(!empty($err)):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="card p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-6"><label>Nama</label><input class="form-control" name="name" value="<?=e($d["name"])?>" required></div><div class="col-md-6"><label>Email</label><input class="form-control" type="email" name="email" value="<?=e($d["email"])?>" required></div><div class="col-md-6"><label>Role</label><select class="form-select" name="role_id"><?php foreach($roles as $r):?><option value="<?=$r["id"]?>" <?=((string)$d["role_id"]===(string)$r["id"])?"selected":""?>><?=e($r["name"])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Password</label><input class="form-control" type="password" name="password" <?=$id?"":"required"?>></div></div><label class="mt-3"><input type="checkbox" name="is_active" <?=$d["is_active"]?"checked":""?>> Akun aktif</label><div class="text-end mt-4"><a href="index.php" class="btn btn-light">Batal</a> <button class="btn btn-primary">Simpan</button></div></form><?php require __DIR__."/../partials/footer.php";?>